"""Proposed product bridges: roles, motivations, handoffs and reciprocal value.
These are design recommendations, not claims about the existing MVP.
"""
BRIDGES=[]
def B(key,title,pair,person,need,yes,no,steps,carry,separate,benefit,signal,priority,related):
 BRIDGES.append(dict(key=key,title=title,pair=pair,person=person,need=need,yes=yes,no=no,steps=steps,carry=carry,separate=separate,benefit=benefit,signal=signal,priority=priority,related=related,page=5+len(BRIDGES)))
B('teacher_support','A teacher can turn expertise into relevant care','Learning centre → Volunteer support',
'An approved Quran teacher','“I teach Quran. I would also like to help someone who needs personal guidance.”',
'Offer volunteering when the teacher wants to give support beyond scheduled classes.',
'A teacher may only publish and teach. Volunteering stays optional.',
[('Teaching profile','Approved topics and languages establish relevant expertise.'),('Choose to help','An invitation offers Quran-related support; the teacher opts in.'),('Volunteer approval','MRM checks suitability, training, capacity and case boundaries.'),('Relevant support match','The seeker sees approved teaching credentials and accepts the offer.')],
'With consent: approved teacher status, verified subject, languages and public profile.',
'Teacher payment does not buy case access. No private student records are shared.',
'The seeker can judge relevant expertise; the teacher gains a meaningful way to serve. Credentials support confidence, not a guarantee of safety.',
'Eligible teachers opting in → approved volunteers → accepted subject-relevant matches.','FIRST', ['volunteer_training','seeker_class','mentoring_support'])
B('volunteer_training','A volunteer can learn before accepting a new task','Volunteer support → Learning centre',
'A volunteer offered unfamiliar work','“I want to help, but I need preparation for this kind of support.”',
'Recommend an approved course when a real duty requires a skill or refresher.',
'Existing qualified volunteers do not repeat irrelevant classes; no blanket course requirement.',
[('Readiness gap','The volunteer or coordinator identifies a specific skill gap.'),('Relevant training','Open the approved course with topic and required outcome explained.'),('Learning evidence','Record completion; assess readiness separately where needed.'),('Return to duty','MRM updates eligibility and offers suitable work after approval.')],
'Course reference, completion and separately assessed competencies, with appropriate visibility.',
'Completion alone is not volunteer approval. Private learning notes stay private.',
'Volunteers get practical preparation; seekers receive help from people approved for the task.',
'Training completion → assessed readiness → eligible task acceptance; monitor support quality.','FIRST',['teacher_support','learner_volunteer','capacity_learning'])
B('seeker_class','A support conversation can open the right learning path','Support requests → Learning centre',
'A seeker asking for Quran-reading help','“I need a patient beginner class, in my language, at a time I can attend.”',
'Suggest a class when learning addresses the person’s expressed need and they want it.',
'Urgent welfare support continues independently. No class enrolment is required for aid.',
[('Expressed need','The assigned helper asks whether learning support would be useful.'),('Consent to refer','The seeker selects a goal, language and availability to share.'),('Suitable programme','Show approved beginner classes and relevant teacher credentials.'),('Optional enrolment','The seeker joins; the helper sees only the agreed referral status.')],
'Chosen learning goal, language, availability and referral ID; share only what is needed.',
'No full case narrative, financial circumstances or private chat enters a teacher profile.',
'The seeker receives a practical next step; teachers reach learners who want the programme.',
'Consented referrals → suitable enrolments → attendance and seeker-reported usefulness.','FIRST',['teacher_support','learning_mentor','mentoring_support'])
B('quran_class','A Quran reader can find help for a specific learning goal','Quran utility → Learning centre',
'A person using Quran reading tools','“I can read this passage, but I want help with pronunciation or meaning.”',
'Offer a discreet learning action after the person explicitly asks for help on a topic.',
'Reading alone remains complete. Do not infer poor skill or send unsolicited judgments.',
[('Ask for guidance','The reader chooses Learn this topic or Get reading help.'),('Choose learning goal','They select beginner reading, recitation or an approved topic.'),('Relevant discovery','Show approved teachers or programmes matching language and level.'),('Return to practice','After learning, a saved link returns to the selected passage.')],
'Only the user-selected passage, learning goal and preferred language.',
'No private reading history or worship-tracker record is shared with a teacher.',
'Daily use can become purposeful learning; teachers receive clearer learner intent.',
'User-initiated learning opens → relevant enrolments → return to chosen practice.','NEXT',['learning_mentor','seeker_class','learner_volunteer'])
B('learning_mentor','A learner can ask for continuity after a class','Learning centre → Mentoring',
'A learner who wants individual follow-up','“The class helped. I would like someone to guide my next steps.”',
'Offer mentoring after a learner requests ongoing guidance or a teacher offers approved capacity.',
'Class enrolment does not enrol a person into mentoring or open private messaging automatically.',
[('Request follow-up','The learner chooses a goal after the programme.'),('Available mentor','Show approved mentors relevant to topic, language and permitted boundaries.'),('Mutual acceptance','The mentor has capacity; the learner agrees to contact and expectations.'),('Ongoing guidance','Open the authorised relationship and optional agreed check-ins.')],
'Chosen programme, learning goal and agreed availability; selected progress only with consent.',
'No automatic access to class rosters, aid cases or private worship records.',
'Learners gain continuity; mentors support people whose needs match their expertise.',
'Follow-up requests → mutually accepted matches → useful agreed check-ins.','NEXT',['seeker_class','mentoring_support','teacher_support'])
B('mentoring_support','A mentor can refer needs beyond the teaching relationship','Mentoring → Support requests',
'A mentor hearing about a practical difficulty','“This learner needs help that I am not authorised or qualified to provide.”',
'Offer a supported referral when the person wants help outside the mentor’s remit.',
'A mentor does not investigate welfare issues or browse existing private cases.',
[('Recognise the limit','The mentor explains the relevant support route without promising an outcome.'),('Person chooses help','The learner opens or agrees to a minimal support referral.'),('MRM triage','Authorised staff assess urgency, eligibility and the appropriate response.'),('Bounded follow-up','The mentor sees only the referral status the person agreed to share.')],
'Consent, chosen category, contact preference and minimum agreed context.',
'No blanket case access. Safeguarding disclosures follow the approved escalation policy.',
'The person reaches qualified help; the mentor can stay within a clear teaching role.',
'Accepted referrals → triaged requests → completed handoffs without excess disclosure.','FIRST',['seeker_class','teacher_support','specialist_referral'])
B('event_volunteer','A learning event can invite a separate service role','Learning events → Volunteer duties',
'A Halaqa attendee or teacher','“I am attending this event. Can I help with registration or accessibility?”',
'Offer clearly defined event tasks when organisers need capacity and the person opts in.',
'Attending a class never creates a duty. An event helper does not gain case access.',
[('Event participation','The person views an approved programme and its support needs.'),('Choose a duty','They select a suitable task, time window and required checks.'),('Coordinator confirms','Check eligibility and avoid conflict with the person’s class time.'),('Event service','Show a separate duty card, instructions and attendance confirmation.')],
'Event ID, chosen slot, contact consent and role-specific eligibility.',
'Class attendance and duty acceptance are separate records; no attendee list is exported.',
'Organisers gain willing capacity; participants have a specific, manageable way to contribute.',
'Opt-in duty requests → conflict-free confirmations → completed event tasks.','NEXT',['learner_volunteer','volunteer_training','feed_learning'])
B('feed_learning','An inspiring post can lead to a relevant programme','Community updates → Learning centre',
'A reader interested in an approved topic','“This article is useful. Where can I learn this with a teacher?”',
'Attach a specific approved programme when it genuinely expands on the post.',
'Not every post needs a conversion. General announcements can stand alone.',
[('Relevant approved post','An author explains a topic with a clear source and audience.'),('Purposeful invitation','Read programme details or Meet the teacher explains the next step.'),('Programme context','Open topic, level, language, date and access information.'),('Voluntary participation','The reader chooses enrolment and can return to the original post.')],
'Post ID, topic and linked programme; aggregate referral attribution where agreed.',
'No sensitive-case targeting, fabricated testimonials or automatic enrolment.',
'Readers can act on genuine interest; teachers reach an appropriate audience.',
'Post-to-programme opens → relevant enrolments; monitor usefulness and opt-outs.','NEXT',['learning_mentor','quran_class','consented_story'])
B('capacity_learning','Repeated support needs can shape better programmes','Support operations → Learning planning',
'An MRM programme coordinator','“We repeatedly receive beginner-learning requests in a language with little capacity.”',
'Use restricted aggregate demand to commission a programme for an evidenced gap.',
'Do not publish identifiable case examples or infer demand from a tiny sensitive group.',
[('Aggregate need','Authorised staff group agreed categories, languages and waiting demand.'),('Plan a response','MRM chooses a topic and suitable approved teacher capacity.'),('Publish programme','Create a public description without beneficiary identities.'),('Measure the response','Track programme capacity, consented referrals and unmet demand.')],
'Only approved aggregate demand, programme requirements and non-identifying outcomes.',
'Case files and individual identities never enter a public programme brief.',
'Learning supply responds to real community needs; support teams gain a useful referral option.',
'Demand gap → commissioned capacity → suitable referrals; review remaining unmet need.','NEXT',['volunteer_training','seeker_class','teacher_support'])
B('consented_story','A verified outcome can invite responsible participation','Service outcomes → Community updates',
'A beneficiary willing to share an experience','“I want to thank the programme, but I want control over what people can see.”',
'Publish a verified, consented story with an appropriate participation destination.',
'Assistance and recognition never depend on agreeing to publicity.',
[('Separate invitation','After service, staff offer an optional story process with no effect on aid.'),('Specific consent','Agree wording, images, visibility and the withdrawal process.'),('Review and publish','Check accuracy, minimisation and moderation before publication.'),('Relevant invitation','Readers can discover a real class or apply to volunteer.')],
'Only approved story assets and programme links under the documented consent.',
'No case narrative, identity number or location is copied by default; no guaranteed outcomes.',
'The storyteller controls disclosure; readers see credible reasons to participate.',
'Consent compliance, correction requests and relevant participation; never reward forced stories.','LATER',['feed_learning','learner_volunteer','capacity_learning'])
B('prayer_event','A local utility can surface a genuinely useful gathering','Prayer / nearby places → Learning events',
'A person checking prayer times or a mosque','“Is there an approved beginner Halaqa near this place?”',
'Offer nearby programmes when the person requests local learning information.',
'Prayer times remain usable without events, location sharing or an account where supported.',
[('Local intent','The person selects a mosque or manually chosen area.'),('Explore gatherings','A separate action requests approved programmes nearby.'),('Check relevance','Show venue, date, topic, language and accessibility information.'),('Choose to attend','The person enrols and optionally enables programme reminders.')],
'Selected venue or area and chosen programme; prefer manual area selection when sufficient.',
'No background location tracking or attendance inference from prayer-tool use.',
'Daily tools create relevant discovery; local organisers reach interested participants.',
'User-requested local discovery → suitable event enrolments → confirmed attendance.','LATER',['event_volunteer','feed_learning','quran_class'])
B('learner_volunteer','A learner can choose a path from participation to contribution','Learning participation → Volunteer application',
'A learner who wants to give back','“This helped me. I want to support others when I am ready.”',
'Offer an optional volunteer path after the person expresses interest in contributing.',
'Learning progress, religiosity or aid receipt never creates an obligation to volunteer.',
[('Interest in service','The learner chooses a suitable contribution area.'),('Relevant preparation','Show actual role expectations and optional or required preparation.'),('Apply and assess','Reuse consented profile details; complete separate volunteer checks.'),('Start within limits','Approved volunteers accept bounded work with coordinator support.')],
'Selected interests, contact details and relevant assessed skills with consent.',
'A certificate, course attendance or worship streak does not confer service authority.',
'Learners gain an achievable contribution route; MRM grows prepared, willing capacity.',
'Interest → applications → approvals → sustained suitable service; watch burden and dropout.','NEXT',['volunteer_training','event_volunteer','teacher_support'])
B('specialist_referral','A volunteer can connect a person to the right specialist','Volunteer support → Specialist referral',
'A volunteer whose assigned case exceeds their remit','“I can accompany this person, but their next need requires authorised expertise.”',
'Route through MRM when a need exceeds the volunteer’s approved competence.',
'The app never treats a teaching badge as legal, medical or financial accreditation.',
[('Recognise a boundary','The volunteer records a minimal referral request on their authorised case.'),('Staff review','MRM checks consent, urgency and the appropriate referral pathway.'),('Approved handoff','Share necessary information with an authorised partner under policy.'),('Keep continuity','Track acknowledgement and next ownership; the volunteer sees permitted status.')],
'Minimum agreed referral context, consent and case/reference ID to authorised recipients.',
'No public case broadcast, unapproved partner access or assumption of specialist credentials.',
'The seeker avoids repeating the story unnecessarily; the volunteer avoids unsafe overreach.',
'Appropriate referrals → acknowledged handoffs → clear next owner and follow-up.','FIRST',['mentoring_support','seeker_class','volunteer_training'])
B('website_journey','Public discovery can continue into the same service journey','Website → App participation',
'A visitor reading a programme or volunteer opportunity','“I want this exact programme, not to start again on a generic home screen.”',
'Preserve the public destination across install, sign-in and eligibility checks where feasible.',
'Public information stays accessible; installation is not needed just to read it.',
[('Specific public page','The visitor chooses a programme, volunteer role or support route.'),('Keep the destination','Carry a non-sensitive link or short reference through entry.'),('Required checks only','Sign in or apply when the selected action requires it.'),('Resume the action','Return to the same programme or application with current availability.')],
'Public destination ID and safe campaign/source reference; no private case data in URLs.',
'No secrets in deep links. Expired programmes receive an honest alternative.',
'Visitors keep their intent; MRM loses fewer people between discovery and participation.',
'Destination retained → intended action completed; test installation and expired-link paths.','FIRST',['feed_learning','learner_volunteer','seeker_class'])
B('recognition_growth','Service experience can guide a person’s next development step','Volunteer review → Learning development',
'A volunteer reflecting with a coordinator','“What did I do well, and what training would help me contribute better?”',
'Use an agreed private review to recommend learning or future duties.',
'Do not convert volunteer hours or popularity into teaching approval or public expertise claims.',
[('Review service','The volunteer and authorised coordinator reflect on a completed duty.'),('Agree development','Select a specific skill goal without copying beneficiary details.'),('Choose learning','Offer an approved course or mentor relevant to that goal.'),('Assess progression','Review learning and suitability before any new responsibility.')],
'Agreed skill goal and restricted competency evidence; public recognition only by policy.',
'No beneficiary story or private feedback on public profiles; no automatic teacher badge.',
'Volunteers see a development path; MRM builds capacity with evidence rather than rank.',
'Agreed plans → useful training → assessed competence; track wellbeing as well as retention.','LATER',['volunteer_training','learner_volunteer','learning_mentor'])
BY_KEY={b['key']:b for b in BRIDGES}
assert len(BRIDGES)==15
assert all(k in BY_KEY for b in BRIDGES for k in b['related'])
